INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0017-000000000000', '운영체제(OS)란 무엇이며 주요 기능은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000001', '프로세스(Process)와 스레드(Thread)의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000002', '프로세스의 상태(state)에는 어떤 것들이 있나요?', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000003', '프로세스 간 통신(IPC)의 방식에는 무엇이 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000004', '컨텍스트 스위칭(Context Switching)은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000005', 'CPU 스케줄링(CPU Scheduling)이란 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000006', 'CPU 스케줄링 알고리즘에는 어떤 것들이 있나요? (예: FCFS, SJF 등)', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000007', 'FCFS와 Round Robin 스케줄링의 차이를 설명하세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000008', '교착 상태(Deadlock)란 무엇이고 발생 조건 4가지는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000009', '교착 상태를 예방하거나 회피하는 방법에는 무엇이 있나요?', 'HARD', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-00000000000a', '은행가 알고리즘(Banker''s Algorithm)은 무엇을 위한 것인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-00000000000b', '가상 메모리(Virtual Memory)란 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-00000000000c', '가상 메모리에서 페이지 교체 알고리즘에는 어떤 것들이 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-00000000000d', '페이지 부재(Page Fault)가 발생하면 어떤 일이 일어나나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-00000000000e', '세그멘테이션(segmentation)과 페이징(paging)의 차이는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-00000000000f', '프로세스의 주소 공간(Address Space)이란 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000010', '메모리 단편화(Fragmentation)란 무엇이며 종류에는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000011', '캐시 메모리(Cache)는 무엇이며 어떻게 동작하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000012', '캐시의 지역성(Locality) 원리는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000013', '스케줄러에는 장기 스케줄러, 단기 스케줄러, 중기 스케줄러가 있습니다. 각 역할은?', 'HARD', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000014', '멀티프로세싱(Multiprocessing)과 멀티스레딩(Multithreading)의 차이는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000015', '유저 모드(User Mode)와 커널 모드(Kernel Mode)의 차이는?', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000016', '시스템 호출(System Call)은 무엇이고 어떤 역할을 하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000017', '인터럽트(Interrupt)는 무엇이며 어떻게 처리되나요?', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000018', '인터럽트와 폴링(Polling)의 차이를 설명해 보세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-000000000019', 'DMA(Direct Memory Access)란 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-00000000001a', '파일 시스템이란 무엇이며, 파일 디스크립터(file descriptor)는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-00000000001b', '저장 장치에서 HDD와 SSD의 차이와 특성은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000017'),
('b0000000-0000-0000-0017-00000000001c', 'RAID란 무엇이며 어떠한 수준(level)들이 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000017');